create_plan.signature:
def create_plan(self, spec: dict, workspace: dict, context: str) -> BuildPlan:
    prompt = f"PILLAR SPEC:\n{json.dumps(spec, indent=2)}\n\nWORKSPACE SUMMARY:\n{json.dumps({k: v for k, v in workspace.items() if k != 'hashes'}, indent=2)}\n\nRELEVANT SOURCE:\n{context}\n\nReturn JSON with:\npillar_id, summary, changes[], tests[], integration_points[].\nEach change must have action=create|modify, path, content, reason.\nDo not modify tests unless needed. Do not touch .git or secrets.\n"
    r = self.model.generate(self.SYSTEM, prompt)
    if r.error or not r.text.strip():
        return BuildPlan(spec['pillar_id'], spec['objective'], tests=['python -m compileall -q .'])
    text = r.text.strip()
    if text.startswith('```'):
        text = text.split('\n', 1)[1].rsplit('```', 1)[0].strip()
    try:
        obj = json.loads(text)
        changes = []
        for c in obj.get('changes', []):
            if c.get('action') in ('create', 'modify') and c.get('path'):
                changes.append(FileChange(**{'action': c['action'], 'path': c['path'], 'content': c.get('content', ''), 'reason': c.get('reason', '')}))
        return BuildPlan(pillar_id=obj.get('pillar_id', spec['pillar_id']), summary=obj.get('summary', spec['objective']), changes=changes, tests=obj.get('tests', ['python -m compileall -q .']), integration_points=obj.get('integration_points', []))
    except Exception:
        return BuildPlan(spec['pillar_id'], spec['objective'], tests=['python -m compileall -q .'])

run.signature:
def run(self, command: List[str], stage: str) -> VerificationResult:
    try:
        p = subprocess.run(command, cwd=self.root, text=True, capture_output=True, timeout=180)
        out = (p.stdout + '\n' + p.stderr)[-12000:]
        return VerificationResult(p.returncode == 0, stage, out, command)
    except subprocess.TimeoutExpired as e:
        return VerificationResult(False, stage, f'timeout: {e}', command)

all.signature:
def all(self) -> List[VerificationResult]:
    results = [self.run([sys.executable, '-m', 'compileall', '-q', '.'], 'compile')]
    pytest = self.root / 'pytest.ini'
    if pytest.exists() or list(self.root.glob('test*.py')) or (self.root / 'tests').exists():
        results.append(self.run([sys.executable, '-m', 'pytest', '-q'], 'pytest'))
    return results

propose.signature:
def propose(self, failure: str, changed_files: list[str], context: str) -> dict | None:
    prompt = f'FAILURE:\n{failure[-12000:]}\n\nCHANGED FILES:\n{json.dumps(changed_files, indent=2)}\n\nSOURCE CONTEXT:\n{context[:30000]}\n'
    r = self.model.generate(self.SYSTEM, prompt)
    if r.error or not r.text.strip():
        return None
    text = r.text.strip()
    if text.startswith('```'):
        text = text.split('\n', 1)[1].rsplit('```', 1)[0].strip()
    try:
        obj = json.loads(text)
        if not obj.get('path') or not isinstance(obj.get('content'), str):
            return None
        return obj
    except Exception:
        return None

snapshot_hash.signature:
def snapshot_hash(self, rel: str) -> str | None:
    p = self.root / rel
    if not p.exists():
        return None
    return hashlib.sha256(p.read_bytes()).hexdigest()

allowed.signature:
def allowed(self, rel: str) -> bool:
    p = Path(rel)
    blocked = {'.git', '.env', 'credentials.json'}
    return not any((part in blocked for part in p.parts)) and (not p.name.endswith(('.key', '.pem')))

scan.signature:
def scan(self) -> Dict[str, Any]:
    modules = []
    imports = {}
    symbols = {}
    hashes = {}
    for p in self.root.rglob('*.py'):
        if any((part in IGNORED for part in p.parts)):
            continue
        try:
            if p.stat().st_size > MAX_BYTES:
                continue
            src = p.read_text(encoding='utf-8')
            rel = str(p.relative_to(self.root))
            tree = ast.parse(src, filename=rel)
            modules.append(rel)
            imports[rel] = sorted({n.module or '' for n in tree.body if isinstance(n, ast.ImportFrom)} | {n.name for n in tree.body if isinstance(n, ast.Import)})
            symbols[rel] = sorted([n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))])
            hashes[rel] = hashlib.sha256(src.encode()).hexdigest()
        except (OSError, UnicodeError, SyntaxError):
            continue
    return {'root': str(self.root), 'python_files': sorted(modules), 'imports': imports, 'symbols': symbols, 'hashes': hashes, 'python_file_count': len(modules)}

_extract_python.signature:
def _extract_python(self, text):
    if not text:
        raise ValueError('Empty model response')
    text = text.strip()
    match = re.search('```(?:python|py)?\\s*(.*?)```', text, flags=re.DOTALL | re.IGNORECASE)
    if match:
        text = match.group(1).strip()
    lines = text.splitlines()
    while lines:
        first = lines[0].strip()
        if (first.startswith(('import ', 'from ', 'class ', 'def ', 'if ')) or first.startswith('#!')) and (not first.startswith('1.')):
            break
        lines.pop(0)
    text = '\n'.join(lines).strip()
    if not text:
        raise ValueError('No Python source detected in output')
    ast.parse(text)
    return text

build_tool.signature:
def build_tool(self, topic, description, failure_context=None):
    filename = generate_tool_name(topic)
    print(f"⚡ [Coder-02] Synthesizing Engine: '{filename}'...")
    repair = ''
    if failure_context:
        repair = f'\nCRITICAL FIX REQUIRED (PREVIOUS FAILURE):\n{failure_context}\nDo NOT block on sys.stdin when running self-tests.\n'
    prompt = f"\nYou are a Python code generation engine.\n\nTASK:\n{topic}\n\nDESCRIPTION:\n{description}\n\n{repair}\n\nSTRICT TECHNICAL CONTRACT:\n1. Return ONLY executable Python 3 source code. Zero markdown or prose.\n2. Use Python standard library modules only.\n3. NON-BLOCKING INPUT: If reading stdin, check `if not sys.stdin.isatty():` or wrap stdin calls inside functions so self-tests run non-interactively without waiting forever.\n4. ENTRY POINT: The script MUST execute its automated self-tests directly inside `if __name__ == '__main__':` and call `sys.exit(0)` on success.\n"
    payload = {'model': 'llama-3.1-8b-instant', 'messages': [{'role': 'system', 'content': 'You are a strict Python generator. Return complete, valid Python source code only.'}, {'role': 'user', 'content': prompt}], 'temperature': 0.0, 'max_tokens': 4096}
    headers = {'Authorization': f'Bearer {self.api_key}', 'Content-Type': 'application/json'}
    for attempt in range(1, 4):
        try:
            response = requests.post(self.url, headers=headers, json=payload, timeout=30)
            if response.status_code == 429:
                wait = min(30, 3 * attempt)
                print(f'⚠️ [Coder-02] Rate limited (429). Retrying in {wait}s...')
                time.sleep(wait)
                continue
            if response.status_code != 200:
                print(f'⚠️ HTTP {response.status_code}: {response.text[:150]}')
                time.sleep(2)
                continue
            raw = response.json()['choices'][0]['message']['content']
            try:
                code = self._extract_python(raw)
                return self._write_verified(filename, code)
            except SyntaxError as e:
                print(f'❌ Syntax Error (Attempt {attempt}): {e}')
                failure_context = f'Generated Python contains SyntaxError at line {e.lineno}: {e.msg}'
                time.sleep(1)
                continue
            except ValueError as e:
                print(f'❌ Extractor Error (Attempt {attempt}): {e}')
                failure_context = str(e)
                time.sleep(1)
                continue
        except Exception as e:
            print(f'⚠️ [Coder-02] Attempt {attempt} Exception: {e}')
            time.sleep(2 ** attempt)
    return None

extract_pure_code.signature:
def extract_pure_code(self, raw_data):
    if isinstance(raw_data, dict):
        raw_data = raw_data.get('code', '')
    raw_str = str(raw_data)
    match = re.search('```python(.*?)```', raw_str, re.DOTALL)
    if match:
        return match.group(1).strip()
    match = re.search('```(.*?)```', raw_str, re.DOTALL)
    if match:
        return match.group(1).strip()
    return raw_str.strip()

execute_python_code.signature:
def execute_python_code(self, code_payload):
    print(f'\n[{self.agent_id}] Extracting and executing Python script...')
    clean_script = self.extract_pure_code(code_payload)
    temp_file = 'temp_runner.py'
    with open(temp_file, 'w', encoding='utf-8') as f:
        f.write(clean_script)
    try:
        res = subprocess.run(['python3', temp_file], capture_output=True, text=True, timeout=10)
        if res.returncode == 0:
            print(f'[{self.agent_id}] Execution Successful!')
            return {'status': 'Success', 'stdout': res.stdout}
        else:
            return {'status': 'Error', 'stdout': res.stderr or 'Execution failed'}
    except Exception as e:
        return {'status': 'Error', 'stdout': str(e)}
    finally:
        if os.path.exists(temp_file):
            os.remove(temp_file)

review_code.signature:
def review_code(self, code_content):
    print(f'🧐 [{self.agent_id}] Scanning code for security risks...')
    for pattern in self.forbidden_patterns:
        if pattern in code_content:
            print(f'❌ [{self.agent_id}] SECURITY ALERT: Dangerous pattern found: {pattern}')
            return False
    if 'from orchestrator' not in code_content and 'def main' not in code_content:
        print(f'⚠️ [{self.agent_id}] Warning: Code structure might be unstable.')
    print(f'✅ [{self.agent_id}] Security Review Passed.')
    return True

analyze_failure.signature:
def analyze_failure(self, sandbox_results):
    stderr = sandbox_results.get('stderr', '')
    exit_code = sandbox_results.get('exit_code', 0)
    if exit_code == -1:
        error_type = 'EXECUTION_TIMEOUT'
        summary = 'The script timed out (>5000ms). Cause: Unbounded input read (e.g. sys.stdin.read()) without EOF or blocking loop. Ensure self-tests do not wait for interactive stdin input.'
    elif 'ModuleNotFoundError' in stderr:
        error_type = 'MISSING_DEPENDENCY'
        summary = stderr[-300:]
    elif 'SyntaxError' in stderr:
        error_type = 'SYNTAX_ERROR'
        summary = stderr[-300:]
    else:
        error_type = 'RUNTIME_CRASH'
        summary = stderr[-300:] if stderr else 'Non-zero exit code'
    print(f'🩹 [Failure Analyzer] Classification: {error_type} | Exit Code: {exit_code}')
    return {'error_type': error_type, 'traceback_summary': summary}

Execute_and_benchmark.signature:
def Execute_and_benchmark(self, script_path):
    print(f"🧪 [Sandbox] Running empirical runtime benchmark on '{script_path}'...")
    start_time = time.time()
    try:
        process = subprocess.run([sys.executable, script_path], capture_output=True, text=True, timeout=5)
        elapsed_ms = (time.time() - start_time) * 1000
        success = process.returncode == 0
        print(f'⏱️ [Sandbox Result] Exit Code: {process.returncode} | Execution Time: {elapsed_ms:.2f}ms')
        return {'executed_successfully': success, 'exit_code': process.returncode, 'execution_time_ms': elapsed_ms, 'stdout': process.stdout[:200], 'stderr': process.stderr[:200]}
    except subprocess.TimeoutExpired:
        print('❌ [Sandbox Result] Process TIMED OUT (>5000ms). Execution terminated.')
        return {'executed_successfully': False, 'exit_code': -1, 'execution_time_ms': 5000, 'stdout': '', 'stderr': 'Execution Timeout Expired'}
    except Exception as e:
        return {'executed_successfully': False, 'exit_code': 1, 'execution_time_ms': 0, 'stdout': '', 'stderr': str(e)}
